/* A track page: filter the entries by objective. The page is generated by
   bin/build.py; this only adds behaviour. The filter lives in the URL
   (#obj=<id>) so a filtered view can be linked, e.g. from an entry page. */
(function () {
  "use strict";

  var buttons = document.querySelectorAll(".ogroups .obj");
  if (!buttons.length) return;

  var rows = document.querySelectorAll(".lrow");
  var empty = document.getElementById("wu-empty");
  var detail = document.getElementById("obj-detail");
  var detailText = document.getElementById("obj-detail-text");
  var clear = document.getElementById("obj-clear");
  var each = function (list, fn) { Array.prototype.forEach.call(list, fn); };

  function current() {
    var m = /(?:^|[#&])obj=([a-z0-9]+(?:-[a-z0-9]+)*)/.exec(window.location.hash);
    return m ? m[1] : null;
  }

  function apply() {
    var id = current(), btn = null;
    each(buttons, function (b) {
      var on = b.getAttribute("data-obj") === id;
      b.setAttribute("aria-pressed", on ? "true" : "false");
      if (on) btn = b;
    });
    if (!btn) id = null;

    var shown = 0;
    each(rows, function (r) {
      r.hidden = !!id && (" " + r.getAttribute("data-objs") + " ").indexOf(" " + id + " ") < 0;
      if (!r.hidden) shown++;
    });
    /* a month heading only shows if one of its entries does */
    each(document.querySelectorAll(".month"), function (m) {
      m.hidden = !m.querySelector(".lrow:not([hidden])");
    });
    if (empty) empty.hidden = rows.length > 0 ? shown > 0 : false;

    detail.hidden = !btn;
    if (btn) {
      detailText.textContent = btn.getAttribute("data-text") + " — " + btn.getAttribute("data-state");
      document.getElementById("entries").scrollIntoView({ block: "start" });
    }
  }

  function reset() {
    history.replaceState(null, "", window.location.pathname);
    apply();
  }

  each(buttons, function (b) {
    b.addEventListener("click", function () {
      var id = b.getAttribute("data-obj");
      if (current() === id) reset();
      else window.location.hash = "obj=" + id;
    });
  });
  if (clear) clear.addEventListener("click", reset);

  window.addEventListener("hashchange", apply);
  apply();
})();
